import { P, R, C, E, Lc, g, face, free, INK } from '../lib.mjs';

const nm = (th, en) => ({ th, en });
// the id follows the file name (cn/harbin/landmark-icepop.v1.svg → cn-harbin.landmark.icepop)
const idOf = (file) => { const [cc, city, base] = file.split('/'); return `${cc}-${city}.landmark.${base.replace(/^landmark-/, '').replace(/\.v\d+\.svg$/, '')}`; };
const L = (file, th, en, kw, sth, sen, svg) => ({ id: idOf(file), cat: 'landmark', file, name: nm(th, en), kw, colour: true, spot: nm(sth, sen), svg: free(svg) });
const sky = (c) => R(-4, -4, 248, 248, c, 0, 0);
const kid = (x, y, top, s = 1) => g(x, y, s, C(0, -20, 8, '#FFE0BD', 2) + P('M-8 4v-16h16v16z', top, 2) + face(0, -18, 0.22));
// a bundled-up child for the Harbin winter (a woolly hat with a bobble)
const snowKid = (x, y, coat, s = 1) => g(x, y, s, C(0, -20, 8, '#FFE0BD', 2) + P('M-9-24c0-12 18-12 18 0z', coat, 2) + C(0, -34, 3, '#FFFFFF', 1.5) + P('M-10 4v-16c0-4 20-4 20 0v16z', coat, 2) + face(0, -18, 0.22));
// n pictures in a row, joined
const range = (n, f) => Array.from({ length: n }, (_, k) => f(k)).join('');
const f1 = (v) => (+v).toFixed(1);
// a karst hill (Guilin)
const hill = (x, w, top, fill = '#7CB342') => P(`M${x - w} 150c0-40 ${w * 0.4}-${150 - top} ${w}-${150 - top}s${w} ${110 - top} ${w} ${150 - top}z`, fill, 3);

